const labelScore=r=>!r?'—':r.mate!==null&&r.mate!==undefined?`${r.cp<0?'−':''}M${Math.abs(r.mate)}`:(r.cp/100>0?'+':'')+(r.cp/100).toFixed(2);
function notify(t){$('message').hidden=!t;$('message').textContent=t}
function badge(type){let t=TYPES[type];return t?`<img class="badge" src="icons/${type}.svg" alt="${t.label}" title="${t.label}" width="24" height="24">`:''}
function renderBoard(){const chess=currentChess(),legal=selected&&exploring?chess.moves({square:selected,verbose:true}).map(m=>m.to):[];let prev=activeBranch?(branchIndex?activeBranch.moves[branchIndex-1]:moves[activeBranch.base-1]):moves[index-1];let html='';for(let row=0;row<8;row++)for(let col=0;col<8;col++){let f=flipped?7-col:col,r=flipped?row:7-row,sq='abcdefgh'[f]+(r+1),p=chess.get(sq);html+=`<button class="square ${(f+r)%2===0?'dark':''} ${sq===selected?'selected':''} ${legal.includes(sq)?'legal':''} ${prev&&(prev.from===sq||prev.to===sq)?'last':''}" data-sq="${sq}" aria-label="${sq}${p?' '+(p.color==='w'?'Bianco ':'Nero ')+names[p.type]:''}" ${busy?'disabled':''}>${p?`<img src="pieces/${p.color}${p.type.toUpperCase()}.png" alt="" draggable="false">`:''}${!activeBranch&&prev?.to===sq&&grades[index-1]?`<span class="board-badge">${badge(grades[index-1].type)}</span>`:''}${col===0?`<span class="coord rank">${r+1}</span>`:''}${row===7?`<span class="coord">${'abcdefgh'[f]}</span>`:''}</button>`}updateBoard($('board'),html);animateBoard($('board'),chess.fen(),flipped,{duration:rapid.running?Math.max(25,rapid.delay-12):undefined,rapid:rapid.running,draw:activeBranch?chess.isDraw():game?(drawAt(moves,index,positions[0])||(index===moves.length&&headers.Result==='1/2-1/2')):chess.isDraw()});celebrateMove($('board'),{key:chess.fen()+':'+(rapid.running?'rapid:':'')+(activeBranch?'branch':grades[index-1]?.type||''),square:prev?.to,type:activeBranch?null:grades[index-1]?.type,enabled:!rapid.running&&getSettings().animation!=='off'&&!matchMedia('(prefers-reduced-motion: reduce)').matches});if(rapid.running)renderReviewArrows($('board'),[],flipped);else drawArrows(prev);renderImportant();let r=currentResult();$('evalNumber').textContent=labelScore(r);$('evalWhite').style.height=(r?Math.max(3,Math.min(97,50+45*Math.tanh(r.cp/450))):50)+'%';$('positionLabel').textContent=activeBranch?`Variante · ${branchIndex}/${activeBranch.moves.length}`:`${index===0?'Posizione iniziale':`Mossa ${new Chess(moves[index-1].before).moveNumber()}${moves[index-1].color==='w'?' · Bianco':' · Nero'}`}`;let n=activeBranch?branchIndex:index,total=activeBranch?activeBranch.moves.length:moves.length;['first','prev'].forEach(k=>$(k).disabled=n===0);['last','next'].forEach(k=>$(k).disabled=n===total);$('topName').textContent=flipped?(headers.White||'Bianco'):(headers.Black||'Nero');$('bottomName').textContent=flipped?(headers.Black||'Nero'):(headers.White||'Bianco');$('topRating').textContent=(flipped?headers.WhiteElo:headers.BlackElo)||' ';$('bottomRating').textContent=(flipped?headers.BlackElo:headers.WhiteElo)||' ';$('topAcc').textContent=flipped?$('whiteAccuracy').textContent:$('blackAccuracy').textContent;$('bottomAcc').textContent=flipped?$('blackAccuracy').textContent:$('whiteAccuracy').textContent;$('boardHint').textContent=busy?'Stockfish sta analizzando. Puoi già leggere le mosse completate.':activeBranch?.lesson?'Usa Avanti e Indietro per seguire le mosse, poi torna alla partita.':activeBranch?.comparison?'Confronto · usa le frecce per esplorare, poi torna alla mossa giocata.':activeBranch?'Variante attiva · muovi entrambi i colori sulla scacchiera.':game?'Seleziona una mossa. In Esplora puoi provare altre continuazioni.':'Importa un PGN per iniziare la revisione.';}
function renderImportant(){if(rapid.running){$('nextImportant').disabled=true;$('importantStatus').textContent='Scorrimento rapido delle mosse…';return;}const target=game?nextImportant(moves,grades,results,index):null;const button=$('nextImportant');button.disabled=!target;button.title=target?target.reason:busy?'Nessun altro momento importante tra le mosse già analizzate':'Nessun altro momento importante rilevato';$('importantStatus').textContent=game?(target?target.reason+' · vai alla mossa '+new Chess(moves[target.index-1].before).moveNumber()+(moves[target.index-1].color==='w'?' del Bianco.':' del Nero.'):busy?'Altri momenti possono emergere durante l’analisi.':'Non ci sono altri momenti importanti rilevati.'):'Analizza una partita per trovare i momenti importanti.';}
$('nextImportant').onclick=async()=>{if(rapid.running)return;const target=nextImportant(moves,grades,results,index);if(!target)return;comparisonToken++;liveId++;activeBranch=null;selected=null;setTab(false);const originalGame=game;const done=await rapid.play(index,target.index,ply=>{index=ply;renderBoard();},{reduced:getSettings().animation==='off'||matchMedia('(prefers-reduced-motion: reduce)').matches});if(done&&game===originalGame){render();$('importantStatus').textContent=target.reason;}};
function renderMoves(){let html='';const rows=[];for(let i=0;i<moves.length;i++){const m=moves[i],num=new Chess(m.before).moveNumber();let row=rows.at(-1);if(!row||row.num!==num){row={num,w:null,b:null};rows.push(row)}row[m.color]=i}for(const row of rows){html+=`<div class="move-row"><span>${row.num}.</span>`;for(const side of ['w','b']){const i=row[side];if(i===null){html+='<span></span>';continue}html+=`<button class="move-button ${!activeBranch&&index===i+1?'current':''}" data-index="${i+1}" title="${grades[i]?TYPES[grades[i].type].label:'Non analizzata'}"><span>${esc(moves[i].san)}</span>${grades[i]?badge(grades[i].type):'<span style="color:#b0b6a8">·</span>'}</button>`}html+='</div>'}$('moves').innerHTML=html;let grade=grades[index-1],move=moves[index-1];if(!index){$('moveInsight').innerHTML='<span class="eyebrow">POSIZIONE INIZIALE</span><h3>La partita comincia qui.</h3><p>Seleziona una mossa per scoprirne la valutazione.</p>';return}renderInsight(move,grade);}
function renderInsight(move,grade){
 if(activeBranch?.lesson){renderLineLesson();return;}
 if(activeBranch?.comparison){renderComparison();return;}
 const host=$('moveInsight'),open=host.dataset.ply===String(index)&&!!host.querySelector('details[open]'),before=grade?.reviewBefore||results[index-1],after=grade?.reviewAfter||results[index];
 const ex=explainMove({move,before,after,grade,opening:openingMap[fenKey(move.after)]});
 const line=(label,fen,lineMoves,kind)=>lineMoves.length?`<section class="explain-line"><h4>${label}</h4><p>${esc(lineStory(fen,lineMoves.map(m=>m.uci),move.color))}</p><button class="secondary wide" data-line="${kind}" ${busy?'disabled':''}>▶ Guarda le mosse sulla scacchiera</button></section>`:'';
 host.dataset.ply=String(index);
 host.innerHTML=`<div class="insight-heading"><div><span class="eyebrow">${new Chess(move.before).moveNumber()}${move.color==='w'?'.':'…'} ${esc(move.san)} · ${move.color==='w'?'BIANCO':'NERO'}</span><h3>${grade?badge(grade.type):''}${grade?TYPES[grade.type].label:'In attesa di analisi'}</h3></div><span class="insight-score">${esc(labelScore(after))}</span></div>${theoryCard(move,grade,openingMap,moves)}<button id="showBestMove" class="primary wide" data-best-move ${busy||comparisonBusy?'disabled':''}>${comparisonBusy?'Confronto in corso…':'Mostra la mossa migliore'}</button><p class="move-action">${esc(ex.action)}</p><p class="move-reason">${esc(ex.reason)}</p>${ex.facts.length?`<div class="position-facts">${ex.facts.slice(0,3).map(t=>`<p>${esc(t)}</p>`).join('')}</div>`:''}<details class="move-details" ${open?'open':''}><summary>Approfondisci questa mossa</summary><details class="analysis-numbers"><summary>Vedi i numeri della valutazione</summary><div class="eval-comparison"><div><span>Prima</span><strong>${esc(scoreText(before))}</strong></div><div><span>Dopo</span><strong>${esc(scoreText(after))}</strong></div></div><p class="metric-note">Valutazioni dal punto di vista del Bianco. ${grade?`Perdita stimata per chi muove: ${(grade.loss*100).toFixed(1)} punti percentuali · precisione della mossa: ${grade.accuracy.toFixed(1)}/100.`:'Analisi ancora incompleta.'}</p></details>${line(ex.same?'La linea migliore parte dalla tua mossa':'Alternativa suggerita',move.before,ex.best,'best')}${line('Come può rispondere l’avversario',move.after,ex.reply,'reply')}<div class="learning-tip"><strong>Da ricordare</strong><p>${esc(ex.tip)}</p></div><p class="metric-note">Le mosse mostrate sono esempi possibili. Le risposte dell’avversario possono cambiare: non sono una previsione della partita.</p></details>`;
 renderReviewCoach(host,move,before,after,grade);
}
function exploreInsightLine(kind){
 if(busy||!game||!index)return;
 const grade=grades[index-1],base=kind==='best'?index-1:index,source=kind==='best'?(grade?.reviewBefore||results[base]):(grade?.reviewAfter||results[base]);
 if(base<0||!source?.lines?.[0]?.pv?.length){notify('Non ho una continuazione verificata per questa posizione.');return;}
 const line=legalVariation(positions[base],source.lines[0].pv);if(!line.moves.length)return;
 liveId++;activeBranch={base,...line,results:[source],lesson:{kind,returnIndex:index}};branchIndex=0;selected=null;render();
 $('moveInsight').querySelector('[data-lesson-next]')?.focus({preventScroll:true});
}
function renderLineLesson(){
 const b=activeBranch,m=branchIndex?b.moves[branchIndex-1]:null;
 $('moveInsight').innerHTML=`<span class="eyebrow">GUARDA COSA SUCCEDE · ${branchIndex}/${b.moves.length}</span><h3>${b.lesson.kind==='reply'?'Una possibile risposta':'Un’altra strada da provare'}</h3><p aria-live="polite">${m?esc(stepStory(m)):'Partiamo dalla posizione prima della sequenza. Premi Avanti: vedrai una mossa alla volta, spiegata qui.'}</p><div class="lesson-controls"><button class="secondary" data-lesson-prev ${!branchIndex?'disabled':''}>← Indietro</button><button class="primary" data-lesson-next ${branchIndex===b.moves.length?'disabled':''}>Avanti →</button></div><p class="metric-note">È un esempio possibile: l’avversario può scegliere altre risposte. La tua partita resta intatta.</p><button class="secondary wide" data-return-game>Torna alla mossa giocata</button>`;
}
$('moveInsight').onclick=e=>{if(e.target.closest('[data-lesson-next]')){navigate(branchIndex+1);return;}if(e.target.closest('[data-lesson-prev]')){navigate(branchIndex-1);return;}if(e.target.closest('[data-best-move]')){void showBestMove();return;}if(e.target.closest('[data-return-game]')){comparisonToken++;liveId++;activeBranch=null;selected=null;render();return;}const button=e.target.closest('[data-line]');if(button)exploreInsightLine(button.dataset.line)};
function renderComparison(){const b=activeBranch,cmp=b.comparison,ex=explainMove({move:b.moves[0],before:cmp.best,after:{lines:[{pv:cmp.best.lines[0].pv.slice(1)}]}}),actual=explainMove({move:moves[index-1],after:{lines:[{pv:cmp.played.lines[0].pv.slice(1)}]}});$('moveInsight').innerHTML=`<span class="eyebrow">CONFRONTO · VARIANTE IPOTETICA</span><h3>${cmp.same?'La tua mossa è già la prima scelta':'Un’altra possibilità'}</h3><div class="eval-comparison"><div><span>Giocata</span><strong>${esc(moves[index-1].san)}</strong></div><div><span>Motore</span><strong>${esc(b.moves[0].san)}</strong></div></div><p>${esc(cmp.verdict.text)}</p><h4>Nell’alternativa</h4><p>${esc(ex.action)}</p><p>${esc(lineStory(moves[index-1].before,cmp.best.lines[0].pv,moves[index-1].color))}</p>${!cmp.same?`<h4>Con la mossa giocata</h4><p>${esc(lineStory(moves[index-1].before,cmp.played.lines[0].pv,moves[index-1].color))}</p>`:''}<p class="metric-note">Le frecce sulla scacchiera distinguono le due scelte dalla stessa posizione. Usa Avanti e Indietro per seguire una possibile continuazione legale per entrambi i colori. Le risposte non sono obbligate. La partita originale non viene modificata.</p><button class="primary wide" data-return-game>Torna alla mossa giocata</button>`;}
async function showBestMove(){
 if(busy||comparisonBusy||!game||index<1)return;
 const move=moves[index-1],source=grades[index-1]?.reviewBefore||results[index-1],token=++comparisonToken,selectedIndex=index;
 if(!source?.lines?.[0]?.pv?.length){notify('Analisi del motore non disponibile per questa mossa. Completa o ripeti la revisione prima del confronto.');return;}
 comparisonBusy=true;notify('Confronto delle due scelte dalla stessa posizione…');renderMoves();
 try{
 const best=await engine.evaluate(move.before,'deep','',{skill:20,limits:[20,4000]});
 const line=legalVariation(move.before,best.lines?.[0]?.pv);if(!line.moves.length)throw Error('Il motore non ha fornito una variante legale.');
 const same=uciOf(line.moves[0])===uciOf(move);
 const played=same?best:await engine.evaluate(move.before,'deep',uciOf(move),{skill:20,limits:[20,4000]});
 if(token!==comparisonToken||index!==selectedIndex||moves[index-1]!==move)return;
 if(!same&&played.lines?.[0]?.pv?.[0]!==uciOf(move))throw Error('Il motore non ha confermato il confronto con la mossa giocata.');
 activeBranch={base:index-1,...line,results:[best],comparison:{same,best,played,verdict:compareEvaluations(best,played,move.color,same)}};branchIndex=0;selected=null;notify('');render();
 }catch(e){if(token===comparisonToken)notify('Confronto non disponibile: '+e.message);}finally{comparisonBusy=false;renderMoves();}
}


function updateAccuracy(){const values=resultAccuracy(moves,results);for(const side of ['w','b'])$(side==='w'?'whiteAccuracy':'blackAccuracy').textContent=values[side]==null?'—':values[side].toFixed(1);renderBoard()}
function renderChart(){const pts=results.map((r,i)=>r?`${(i/Math.max(1,moves.length))*600},${45-40*Math.tanh(r.cp/500)}`:null).filter(Boolean);$('chart').innerHTML=`<line x1="0" y1="45" x2="600" y2="45" stroke="#d7dcd5" stroke-dasharray="4 4"/>${pts.length>1?`<polyline points="${pts.join(' ')}" fill="none" stroke="#77935e" stroke-width="2.2" stroke-linejoin="round"/>`:''}${results[index]?`<circle cx="${index/Math.max(1,moves.length)*600}" cy="${45-40*Math.tanh(results[index].cp/500)}" r="4" fill="#254a37"/>`:''}`}
function render(){$('cancel').hidden=!busy;$('resumeAnalysis').hidden=!game||busy||grades.filter(Boolean).length===moves.length;document.body.classList.toggle('review-loaded',!!game);fitReviewBoard();$('analysisLesson').hidden=!game;if(game){const ac=resultAccuracy(moves,results);for(const side of ['w','b']){const prefix=side==='w'?'white':'black',f=gameDecisions(moves,results,side);$(prefix+'Performance').textContent=performanceEstimate(moves,grades,side,results).text;$(prefix+'Facts').textContent=['Accuracy: '+(ac[side]==null?'—':ac[side].toFixed(1)+'%'),f.tactical?'Scelte tattiche trovate: '+f.found+'/'+f.tactical:'Nessuna scelta tattica distintiva verificata', (f.openingPairs?'Stesso pezzo mosso di nuovo nei primi 10 turni: '+f.repeated+'/'+f.openingPairs:'')].join('\n')}}renderBoard();renderMoves();renderChart();renderBranches()}
async function importGame(){if(busy||importing)return;rapid.cancel();notify('');const text=$('pgn').value.trim();if(!text){notify('Incolla il testo PGN o carica un file prima di avviare l’analisi.');return}if(text.length>1000000){notify('Il file è troppo grande. Importa una sola partita.');return}importing=true;try{if((text.match(/\[Event\s/g)||[]).length>1)throw Error('Il testo contiene più partite. Importane una alla volta.');let c=new Chess();c.loadPgn(text,{strict:false});let ms=c.history({verbose:true});if(!ms.length)throw Error('Non ci sono mosse da analizzare nel PGN.');if(text!==pendingText){archiveId=null;pendingSide=null}game=c;headers=c.getHeaders();for(const key of ['White','Black'])if(headers[key]==='?')headers[key]=key==='White'?'Bianco':'Nero';$('playerSide').value=pendingSide||inferSide(headers)||'';moves=ms;positions=[ms[0].before,...ms.map(m=>m.after)];const saved=await getRecord(archiveId||await gameId(c.pgn())).catch(()=>null);const checkpoint=restoreCheckpoint(saved?.analysis?.checkpoint,ms);results=checkpoint?.results||[];grades=checkpoint?.grades||[];archiveId=saved?.id||archiveId;if(saved?.side&&!pendingSide)$('playerSide').value=saved.side;index=0;branches=[];activeBranch=null;selected=null;liveId++;$('importPanel').hidden=true;$('loadedPanel').hidden=false;$('gameResult').textContent=headers.Result||'*';setTab(false);render();try{await navigator.storage?.persist?.()}catch{}if(checkpoint){await loadBook();updateAccuracy();render();$('reanalyze').hidden=false;$('progressText').textContent=`Revisione recuperata · ${grades.length}/${moves.length} mosse`;$('progressFill').style.width=100*grades.length/moves.length+'%';$('saveStatus').textContent='Analisi salvata recuperata. Puoi riprenderla oppure ricalcolarla da capo.';return;}await persistReview().catch(()=>notify('Archivio non disponibile: esporta il PGN per conservarlo.'));await analyzeGame()}catch(e){notify('Importazione o analisi: '+e.message)}finally{importing=false}}
async function analyzeGame(resume=false){
 if(busy||!game)return;setTab(false);busy=true;const id=++runId;
 $('reanalyze').hidden=true;$('cancel').hidden=false;$('cancel').disabled=false;$('progressArea').hidden=false;$('analyze').disabled=true;$('exploreTab').disabled=true;
 if(!resume){results=[];grades=[];}updateAccuracy();render();
 try{
  await Promise.all([engine.init(),loadBook()]);
  const historyPosition=reviewHistory(moves,positions[0]);
  await continueReview({positions,moves,results,grades,stopped:()=>id!==runId,
   evaluate:async(fen,i)=>{ $('progressText').textContent=`Analisi posizione ${i+1} di ${positions.length}…`;const c=historyPosition(i);return terminal(c)||await engine.evaluate(fen,quality());},
   grade:(move,before,after,previousLoss)=>checkedGrade(engine,{move,before,after,openings:openingMap,previousLoss}),
   onSaved:async count=>{updateAccuracy();if(!rapid.running){renderMoves();renderChart();renderBoard();}$('progressFill').style.width=100*count/moves.length+'%';await persistReview();}
  });
  $('progressText').textContent=grades.length===moves.length?`Revisione completata · ${moves.length} mosse analizzate`:`Analisi interrotta · ${grades.length}/${moves.length} mosse. Premi Riprendi analisi.`;
 }catch(e){notify(e.message);$('saveStatus').textContent='Salvataggio o analisi non completati: conserva il PGN; puoi riprovare con Riprendi analisi.';$('progressText').textContent='Analisi incompleta · risultati disponibili conservati';}
 finally{busy=false;$('analyze').disabled=false;$('newGame').disabled=false;$('exploreTab').disabled=false;$('cancel').hidden=true;$('reanalyze').hidden=false;render();await persistReview().catch(()=>{$('saveStatus').textContent='Salvataggio non riuscito. Non chiudere la pagina senza esportare il PGN.'});if(resetRequested)resetReview();}
}

function setTab(explore){comparisonToken++;if(explore&&activeBranch?.comparison)activeBranch=null;if(explore&&!game){notify('Importa prima una partita per esplorare le varianti.');return}if(explore&&busy)return;exploring=explore;$('reviewTab').classList.toggle('active',!explore);$('exploreTab').classList.toggle('active',explore);$('reviewContent').hidden=explore;$('exploreContent').hidden=!explore;if(!explore){activeBranch=null;liveId++;selected=null;render()}else{render();liveAnalyze()}}
function newBranch(analyze=true){if(!game||busy)return;if(activeBranch){const old=activeBranch;activeBranch={id:Date.now()+Math.random(),base:old.base,positions:old.positions.slice(0,branchIndex+1),moves:old.moves.slice(0,branchIndex),results:old.results.slice(0,branchIndex+1)}}else{activeBranch={id:Date.now()+Math.random(),base:index,positions:[positions[index]],moves:[],results:[results[index]]};branchIndex=0}branches.push(activeBranch);render();if(analyze)liveAnalyze()}
function renderBranches(){$('branches').innerHTML='<option value="">Partita originale</option>'+branches.map((b,i)=>`<option value="${b.id}" ${b===activeBranch?'selected':''}>Variante ${i+1} · dopo ${b.base===0?'inizio':`${Math.ceil(b.base/2)}${b.base%2?'.':'…'} ${esc(moves[b.base-1].san)}`}</option>`).join('');$('branchMoves').innerHTML=activeBranch?`<button data-ply="0" class="${branchIndex===0?'current':''}">Inizio</button>`+activeBranch.moves.map((m,i)=>`<button data-ply="${i+1}" class="${branchIndex===i+1?'current':''}">${m.color==='w'?`${new Chess(activeBranch.positions[i]).moveNumber()}.`:''}${esc(m.san)}</button>`).join(''):'<p class="muted">La posizione selezionata nella revisione è il tuo punto di partenza.</p>'}
function pvText(fen,pv){const c=new Chess(fen);const out=[];for(const u of pv.slice(0,10)){try{let n=c.moveNumber(),color=c.turn(),m=c.move({from:u.slice(0,2),to:u.slice(2,4),promotion:u[4]||'q'});out.push((color==='w'?n+'. ':out.length===0?n+'… ':'')+m.san)}catch{break}}return out.join(' ')}
async function liveAnalyze(){const token=++liveId;liveResult=null;$('playBest').disabled=true;if(!exploring||busy)return;const fen=currentFen(),c=currentChess();$('liveScore').textContent='—';let end=terminal(c);$('pv').textContent=end?end.terminal:'Analisi della posizione…';if(end){if(activeBranch)activeBranch.results[branchIndex]=end;$('liveScore').textContent=labelScore(end);renderBoard();return}try{const r=await engine.evaluate(fen,quality());if(token!==liveId||currentFen()!==fen)return;liveResult=r;if(activeBranch)activeBranch.results[branchIndex]=r;$('liveScore').textContent=labelScore(r);$('pv').textContent='Premi Gioca la migliore per vedere la prossima mossa sulla scacchiera.';$('playBest').disabled=!r.best;renderBoard()}catch(e){if(token===liveId){notify(e.message);$('pv').textContent='Motore non disponibile. Puoi comunque esplorare le mosse legali.'}}}
async function playMove(from,to,promotion){if(!exploring||busy||!game)return;const c=currentChess();const candidates=c.moves({square:from,verbose:true}).filter(m=>m.to===to);if(!candidates.length)return;if(candidates.some(m=>m.promotion)&&!promotion){promotion=await choosePromotion(c.turn());if(!promotion)return}const move=c.move({from,to,promotion:promotion||'q'});if(!move)return;if(!activeBranch||branchIndex<activeBranch.moves.length)newBranch(false);playSound();activeBranch.moves.push(move);activeBranch.positions.push(c.fen());branchIndex=activeBranch.moves.length;selected=null;render();liveAnalyze()}
function choosePromotion(color){return new Promise(resolve=>{$('promotionOptions').innerHTML=['q','r','b','n'].map(p=>`<button data-piece="${p}" aria-label="${names[p]}"><img src="pieces/${color}${p.toUpperCase()}.png" alt="${names[p]}"></button>`).join('');$('promotion').showModal();let done=p=>{$('promotion').close();$('promotionOptions').onclick=null;$('promotion').oncancel=null;resolve(p)};$('promotionOptions').onclick=e=>{let b=e.target.closest('[data-piece]');if(b)done(b.dataset.piece)};$('cancelPromotion').onclick=()=>done(null);$('promotion').oncancel=e=>{e.preventDefault();done(null)}})}
function navigate(n){selected=null;if(activeBranch)branchIndex=Math.max(0,Math.min(activeBranch.moves.length,n));else index=Math.max(0,Math.min(moves.length,n));render();if(exploring&&!activeBranch?.lesson)liveAnalyze()}
$('board').onclick=e=>{let b=e.target.closest('[data-sq]');if(!b||busy)return;if(!exploring||activeBranch?.lesson){if(game){selected=selected===b.dataset.sq?null:b.dataset.sq;renderBoard()}return}let sq=b.dataset.sq,c=currentChess(),p=c.get(sq);if(selected&&c.moves({square:selected,verbose:true}).some(m=>m.to===sq)){playMove(selected,sq);return}selected=p&&p.color===c.turn()?sq:null;renderBoard()};
$('moves').onclick=e=>{let b=e.target.closest('[data-index]');if(b){comparisonToken++;activeBranch=null;index=Number(b.dataset.index);selected=null;render()}};
$('branchMoves').onclick=e=>{let b=e.target.closest('[data-ply]');if(b)navigate(Number(b.dataset.ply))};
$('branches').onchange=e=>{activeBranch=branches.find(b=>String(b.id)===e.target.value)||null;branchIndex=activeBranch?.moves.length||0;selected=null;render();liveAnalyze()};
$('original').onclick=()=>{if(activeBranch)index=activeBranch.base;activeBranch=null;selected=null;render();liveAnalyze()};$('addBranch').onclick=()=>newBranch();
$('playBest').onclick=()=>{if(liveResult?.best){const u=liveResult.best;playMove(u.slice(0,2),u.slice(2,4),u[4])}};
$('first').onclick=()=>navigate(0);$('prev').onclick=()=>navigate((activeBranch?branchIndex:index)-1);$('next').onclick=()=>navigate((activeBranch?branchIndex:index)+1);$('last').onclick=()=>navigate(activeBranch?activeBranch.moves.length:moves.length);$('flip').onclick=()=>{flipped=!flipped;renderBoard()};
$('reviewTab').onclick=()=>setTab(false);$('exploreTab').onclick=()=>setTab(true);$('analyze').onclick=importGame;$('reanalyze').onclick=()=>analyzeGame(false);$('resumeAnalysis').onclick=()=>analyzeGame(true);$('cancel').onclick=()=>{runId++;$('cancel').disabled=true;$('progressText').textContent='Interruzione dopo la posizione corrente…';setTimeout(()=>$('cancel').disabled=false,2500)};
$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1000000){notify('Carica un file con una sola partita, inferiore a 1 MB.');return}$('pgn').value=await f.text();notify('File caricato. Premi “Analizza partita” per iniziare.');e.target.value=''};
function resetReview(){rapid.cancel();comparisonToken++;if(busy){resetRequested=true;runId++;$('progressText').textContent='Chiudo l’analisi corrente…';return}resetRequested=false;runId++;liveId++;game=null;positions=[new Chess().fen()];moves=[];results=[];grades=[];headers={};index=0;selected=null;exploring=false;branches=[];activeBranch=null;branchIndex=0;liveResult=null;archiveId=null;pendingText='';pendingSide=null;$('pgn').value='';$('file').value='';$('playerSide').value='';$('whiteAccuracy').textContent='—';$('blackAccuracy').textContent='—';$('importPanel').hidden=false;$('loadedPanel').hidden=true;$('progressFill').style.width='0%';$('progressText').textContent='In attesa';$('cancel').disabled=false;setTab(false);notify('Pronto per una nuova partita. Quelle già salvate restano in Progressi.');$('pgn').focus();$('importPanel').scrollIntoView({behavior:'smooth',block:'nearest'})}
$('newGame').onclick=resetReview;$('resetAnalysis').onclick=resetReview;
$('demo').onclick=()=>{$('pgn').value='[Event "Partita dimostrativa"]\n[White "Bianco"]\n[Black "Nero"]\n[Result "1-0"]\n\n1. Nf3 d6 2. e4 Nf6 3. e5 dxe5 4. Nxe5 g6 5. Bc4 Be6 6. Bxe6 fxe6 7. d3 Bg7 8. Qf3 Nd5 9. Qf7# 1-0';importGame()};
$('chart').onclick=e=>{if(!game)return;const rect=$('chart').getBoundingClientRect();activeBranch=null;navigate(Math.round((e.clientX-rect.left)/rect.width*moves.length))};
$('export').onclick=()=>{if(!game){notify('Importa una partita prima di esportare.');return}const c=new Chess(positions[0]);for(const [k,v] of Object.entries(headers))c.setHeader(k,v);const list=activeBranch?[...moves.slice(0,activeBranch.base),...activeBranch.moves]:moves;for(const m of list)c.move({from:m.from,to:m.to,promotion:m.promotion||'q'});if(activeBranch){c.setHeader('Event',(headers.Event||'Partita')+' — Variante');c.setHeader('Result',c.isCheckmate()?(c.turn()==='w'?'0-1':'1-0'):c.isDraw()?'1/2-1/2':'*')}const url=URL.createObjectURL(new Blob([c.pgn()],{type:'application/x-chess-pgn'}));let a=document.createElement('a');a.href=url;a.download=activeBranch?'plystreak-variante.pgn':'plystreak-partita.pgn';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)};
$('methodButton').onclick=()=>$('method').showModal();$('closeMethod').onclick=()=>$('method').close();document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;if(e.key==='ArrowLeft'){e.preventDefault();$('prev').click()}if(e.key==='ArrowRight'){e.preventDefault();$('next').click()}});
$('legend').innerHTML=Object.keys(TYPES).map(t=>`<span>${badge(t)} ${TYPES[t].label}</span>`).join('');render();

$("quality").value=getSettings().quality;window.addEventListener("ply-settings",()=>{$("quality").value=getSettings().quality;render()});
try{if(new URLSearchParams(location.search).has("training")){const p=localStorage.getItem("plystreak-review-import");if(p){$("pgn").value=p;pendingText=p;archiveId=localStorage.getItem("plystreak-review-id")||null;pendingSide=localStorage.getItem("plystreak-review-side")||null;localStorage.removeItem("plystreak-review-id");localStorage.removeItem("plystreak-review-side");notify("Allenamento caricato. Premi Analizza partita per la revisione completa.");localStorage.removeItem("plystreak-review-import");if(new URLSearchParams(location.search).get("review")==="auto"){history.replaceState(null,"",location.pathname);void importGame()}}}}catch{}

$("playerSide").onchange=()=>{render();if(game)persistReview().then(()=>notify("Colore salvato: statistiche ed esercizi useranno le tue mosse.")).catch(()=>notify("Salvataggio del colore non riuscito."))};

$('restoreLastReview').onclick=async()=>{if(busy)return;try{const id=localStorage.getItem('plystreak-last-review'),saved=id?await getRecord(id):null;if(!saved){notify('Nessuna analisi recente disponibile. Le altre partite sono in Progressi.');return;}archiveId=saved.id;pendingText=saved.pgn;pendingSide=saved.side;$('pgn').value=saved.pgn;await importGame();}catch(e){notify('Recupero non riuscito: '+e.message)}};
try{$('restoreLastReview').hidden=!localStorage.getItem('plystreak-last-review')}catch{}
